/** The three cross-fading slides of the "Our Projects" showcase. */
/* 홈 "Our Projects" 슬라이드 한 장.

   개수는 어드민에서 [메인] 을 체크한 수를 따른다 — **최대 5장**.
   ⚠️ 예전엔 3장 고정이었다. public/js/main.js 가 `for(i<3)` · `Math.min(2,…)` ·
      `MAXSTEP=3` 으로 3 을 박아 놨기 때문이다. 지금은 그 런타임이 DOM 에서 레이어
      수를 세도록 고쳤다(`COUNT`/`LAST`). 5를 넘겨 늘리려면 CSS 의
      `.proj-vis:nth-child(n)` z-index 도 같이 늘려야 한다. */
export type ShowcaseItem = {
  /** portfolios.id — 시트가 여는 주소(/projects/<id>)의 근거. 기본 슬라이드는 '' */
  id: string;
  name: readonly string[];
  client: string;
  launch: string;
  image: string;
  background: string;
  /** 상세가 등록된 것만 링크가 된다 — 없으면 클릭해도 아무 일 없음 (ProjectCard 와 같은 규칙) */
  href: string | null;
  /** 시트가 iframe 에 넣을 상세 경로. href 와 짝이다 */
  detail: string | null;
};

/** 슬라이드 상한 = 메인 등록 상한(3). 어드민이 4건째를 아예 못 걸므로 잘릴 일이 없다.

    순서는 어드민 포트폴리오 목록의 **No 순서**다 — 홈 쿼리가 `is_main` 인 행을
    `sort_order` 오름차순으로 읽는다.

    ⚠️ 늘리려면 `MAX_MAIN`(lib/portfolios.ts) · `style.css` 의 `.proj-vis:nth-child`
    z-index · `015` 의 DB 트리거를 **셋 다** 같이 늘려야 한다. */
export const MAX_SHOWCASE = MAX_MAIN;

